// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../state.js";
import "../wizard/create_new.js";
import "./data_library.js";

/* School templates — seed a working school from a school-type choice.
 *
 * Consumes window.OnboardingData (shipped in data_library.js).
 * Exposes window.SchoolTemplates.{ choices, applyChoice(id, opts) }.
 *
 * Triggered from the wizard's "Create new" flow. Each choice loads
 * subjects + 1 sample teacher + 1 sample class + a bell schedule.
 */
(function (global) {
  "use strict";

  function ensure(condition, message) {
    if (!condition) console.warn("[school-templates]", message);
  }

  const CHOICES = [
    { id: "cbse",              label: "CBSE school (India)",          subj: "cbse",
      classes: "Indian primary",  bell: "Indian 6-day 8-period",       names: "indian",
      subtitle: "8+ subjects · 6 days × 8 periods" },
    { id: "ib_myp",            label: "IB MYP school",                subj: "ib_myp",
      classes: "Indian primary",  bell: "Western 5-day 7-period",      names: "western",
      subtitle: "8+ subjects · 5 days × 7 periods" },
    { id: "igcse",             label: "IGCSE school",                 subj: "igcse",
      classes: "Indian secondary", bell: "Western 5-day 7-period",     names: "western",
      subtitle: "8+ subjects · 5 days × 7 periods" },
    { id: "us_k12",            label: "US public school K-12",        subj: "us_k12",
      classes: "Western K-5",     bell: "Western 5-day 7-period",      names: "western",
      subtitle: "8+ subjects · 5 days × 7 periods" },
    { id: "montessori_primary", label: "Montessori primary",          subj: "montessori_primary",
      classes: "Montessori",      bell: "Montessori 5-day 4-cycle",    names: "western",
      subtitle: "8+ subjects · 5 days × 4 cycles" },
    { id: "india_govt",        label: "Govt school (India)",          subj: "india_govt",
      classes: "Indian primary",  bell: "Indian 6-day 8-period",       names: "indian",
      subtitle: "8+ subjects · 6 days × 8 periods" },
    { id: "blank",             label: "Blank — I'll set up everything", subj: null, classes: null, bell: null, names: null,
      subtitle: "Start empty and add your own subjects, teachers, and classes" },
  ];

  function applyChoice(id, opts) {
    opts = opts || {};
    const choice = CHOICES.find(c => c.id === id);
    if (!choice) return { error: "no such template: " + id };
    const APP = global.APP || (global.APP = {});
    if (!global.CreateNew?.createBlank) return { error: "CreateNew not loaded" };
    // Do NOT use the picker label as the school name: it turned "Blank — I'll set
    // up everything" (and "CBSE school (India)") into the school's name, which
    // then printed on every report. Only an explicit name is passed through;
    // otherwise createBlank's neutral default applies and the user sets it in
    // School settings.
    global.CreateNew.createBlank(opts.schoolName ? { schoolName: opts.schoolName } : {});
    const school = APP.school;
    school.schemaVersion = school.schemaVersion || 1;
    if (choice.id === "blank") {
      return { ok: true, choice: "blank" };
    }
    const data = global.OnboardingData;
    if (!data) {
      ensure(false, "OnboardingData missing — seeding skeleton only");
      return { ok: true, choice: "blank-fallback" };
    }
    global.APP.mutate(`Apply ${choice.label} template`, (currentSchool) => {
      // Seed subjects
      if (choice.subj && data.SUBJECTS[choice.subj]) {
        currentSchool.subjects = data.SUBJECTS[choice.subj].map((s, i) => ({
          id: "s_" + i + "_" + Math.random().toString(36).slice(2, 6),
          name: s.name, abbr: s.short, color: s.color,
          contractWeight: s.weight,
        }));
      }
      // Seed bell schedule
      if (choice.bell && data.BELLS[choice.bell]) {
        const bell = data.BELLS[choice.bell];
        currentSchool.bell = { periods: bell.periods.map((p, i) => ({
          index: i + 1, label: p.label, startMin: p.startMin, endMin: p.endMin, isTeaching: true,
        })) };
        // Seed breaks
        if (bell.breaks?.length) {
          currentSchool.breaks = bell.breaks.map((b, i) => ({
            id: "b_" + i, name: b.name, startMin: b.startMin, endMin: b.endMin,
            afterPeriod: b.afterPeriod,
          }));
        }
        currentSchool.daysPerWeek = bell.daysPerWeek;
      }
      // Seed sample classes
      if (choice.classes && data.CLASS_PATTERNS[choice.classes]) {
        currentSchool.classes = data.CLASS_PATTERNS[choice.classes].slice(0, 3).map((name, i) => ({
          id: "c_" + i + "_" + Math.random().toString(36).slice(2, 6),
          name, short: name, color: "#3b82f6",
        }));
      }
      // Seed one sample teacher
      if (choice.names && data.TEACHER_NAMES[choice.names]?.length) {
        const t = data.TEACHER_NAMES[choice.names][0];
        currentSchool.teachers = [{
          id: "t_seed", name: t + " — replace with real teachers", color: "#10b981",
        }];
      }
      // Seed two sample rooms
      const roomPattern = data.ROOM_PATTERNS["Numbered"];
      if (roomPattern) {
        currentSchool.classrooms = roomPattern.slice(0, 2).map((name, i) => ({
          id: "r_" + i, name, short: name,
        }));
      }
    });
    if (global.CreateNew?.refreshIndex) global.CreateNew.refreshIndex();
    if (global.APP?.audit?.append) {
      global.APP.audit.append({ entity: "school", op: "template-applied", template: id });
    }
    return { ok: true, choice: id, counts: {
      subjects: school.subjects?.length || 0,
      classes:  school.classes?.length  || 0,
      teachers: school.teachers?.length || 0,
      rooms:    school.classrooms?.length || 0,
    }};
  }

  /* ── UI: template picker modal (only shown if user clicks "Create new") ── */
  function pickerHtml() {
    const tiles = CHOICES.map(c =>
      `<button type="button" data-id="${c.id}" class="chrx-tpl-card${c.id === "blank" ? " chrx-tpl-card--full" : ""} chrx-lift chrx-press">
         <strong>${c.label}</strong>
         <small>${c.subtitle || ""}</small>
       </button>`
    ).join("");
    return `
      <h3 class="chrx-tpl-title">Pick a starting point</h3>
      <p class="chrx-tpl-sub">We'll seed subjects, a bell schedule, and 3 sample classes. You can change everything later.</p>
      <div class="chrx-tpl-grid">${tiles}</div>`;
  }

  function ensureStyles() {
    if (document.getElementById("chrx-tpl-styles")) return;
    const s = document.createElement("style");
    s.id = "chrx-tpl-styles";
    s.textContent = `
.chrx-tpl-modal{position:fixed;inset:0;background:rgba(15,23,42,.58);backdrop-filter:blur(4px);display:flex;align-items:center;justify-content:center;padding:24px;z-index:1100}
.chrx-tpl-modal__panel{background:var(--chrx-bg-elev,#fff);color:var(--chrx-fg,#0f172a);border:1px solid var(--chrx-line,#e2e8f0);border-radius:14px;width:min(680px,95vw);padding:24px 26px;box-shadow:0 24px 64px rgba(15,23,42,.3);font-family:var(--chrx-font-sans,"DM Sans",-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif)}
.chrx-tpl-modal__panel:focus{outline:none}
.chrx-tpl-title{margin:0 0 6px;font-family:var(--chrx-font-sans,"DM Sans",-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif);font-size:20px;font-weight:700;letter-spacing:-0.02em;color:var(--chrx-fg,#0f172a)}
.chrx-tpl-sub{margin:0 0 18px;font-family:var(--chrx-font-sans,"DM Sans",-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif);font-size:13.5px;line-height:1.5;color:var(--chrx-fg-secondary,#64748b)}
.chrx-tpl-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
@media (max-width:560px){.chrx-tpl-grid{grid-template-columns:1fr}}
.chrx-tpl-card{background:var(--chrx-bg-tile,#f8fafc);border:1px solid var(--chrx-line,#e2e8f0);color:var(--chrx-fg,#0f172a);text-align:left;padding:14px 16px;border-radius:10px;cursor:pointer;transition:background .15s ease,border-color .15s ease,transform .15s ease;display:flex;flex-direction:column;gap:4px;font-family:inherit}
.chrx-tpl-card--full{grid-column:1 / -1}
.chrx-tpl-card:hover,.chrx-tpl-card:focus-visible{background:var(--chrx-bg-elev,#fff);border-color:var(--chrx-accent,#0d4f54);transform:translateY(-1px);outline:none;box-shadow:0 0 0 3px var(--chrx-accent-bg,rgba(13,79,84,.12))}
.chrx-tpl-card strong{font-size:14px;font-weight:600;color:var(--chrx-fg,#0f172a)}
.chrx-tpl-card small{color:var(--chrx-fg-secondary,#64748b);font-size:12px}
.chrx-tpl-foot{display:flex;justify-content:flex-end;margin-top:16px;padding-top:12px;border-top:1px solid var(--chrx-line,#e2e8f0)}
.chrx-tpl-cancel{background:transparent;border:1px solid var(--chrx-line,#cbd5e1);color:var(--chrx-fg,#0f172a);padding:7px 14px;border-radius:8px;font-size:13px;font-weight:500;cursor:pointer;font-family:inherit}
.chrx-tpl-cancel:hover{background:var(--chrx-bg-tile,#f1f5f9)}
    `;
    document.head.appendChild(s);
  }

  function showPicker(onPick) {
    // Bug #2: don't stack duplicate pickers if the user clicks "+ New" twice.
    const existing = document.querySelector(".chrx-tpl-modal");
    if (existing) existing.remove();
    ensureStyles();
    const root = document.createElement("div");
    root.className = "chrx-tpl-modal";
    root.onclick = e => { if (e.target === root) root.remove(); };
    const panel = document.createElement("div");
    panel.className = "chrx-tpl-modal__panel";
    panel.innerHTML = pickerHtml();
    root.appendChild(panel);
    document.body.appendChild(root);
    panel.querySelectorAll("[data-id]").forEach(btn => {
      btn.onclick = () => {
        const id = btn.dataset.id;
        const r = applyChoice(id);
        root.remove();
        if (onPick) onPick(id, r);
      };
    });
  }

  global.SchoolTemplates = { CHOICES, applyChoice, showPicker };
})(window);

// [vite-esm] exports auto-generated by the 2026-07 Vite migration.
export const SchoolTemplates = window.SchoolTemplates;
